SUF = dict(Lirası='dır', kuruş='tur', Dolar='dır', sent='tir', Euro='dur', Sterlini='dir', peni='dir')
def amt(x, c):
    cents = int(round(abs(num(x)) * 100))
    whole = cents // 100
    frac = cents % 100
    s = str(whole)
    out = ''
    while len(s) > 3:
        out = '.' + s[-3:] + out
        s = s[:-3]
    out = s + out
    t = out + ' ' + CUR[c][0]
    if frac:
        t = t + ' ' + str(frac) + ' ' + CUR[c][1]
    return t
def fin(t):
    return t + "'" + SUF.get(t.split(' ')[-1], 'dir') + '.'
def spaced(d):
    return ' '.join(list(str(d)))
def norm(s):
    s = str(s)
    for a, b in (('İ', 'i'), ('I', 'ı'), ('Ş', 'ş'), ('Ğ', 'ğ'), ('Ü', 'ü'), ('Ö', 'ö'), ('Ç', 'ç')):
        s = s.replace(a, b)
    s = s.lower()
    s = re.sub(r'[^a-z0-9ığüşöç ]', ' ', s)
    return ' '.join(s.split())
def cards():
    pre = 'list_cards_response.data.data.cards.'
    idx = set()
    for k in list(vars.keys()):
        if str(k).startswith(pre):
            p = str(k)[len(pre):].split('.')
            if p[0].isdigit():
                idx.add(int(p[0]))
    out = []
    for i in sorted(idx):
        b = pre + str(i) + '.'
        cn = sv(b + 'cardNumber')
        if not cn:
            continue
        name = sv(b + 'productName').strip()
        if len(name) > 30:
            name = ''
        l4 = sv(b + 'cardNumberLast4') or cn[-4:]
        out.append(dict(n=cn, l4=l4, name=name, main=(sv(b + 'isMainCard').lower() != 'false')))
    return out
def cname(c):
    if c['name']:
        return c['name']
    return 'sonu ' + spaced(c['l4']) + ' ile biten kart'
def sel_question(cs):
    ex = []
    for c in cs:
        if c['main'] and c['name'] and c['name'] not in ex:
            ex.append(c['name'])
    if len(ex) >= 2:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
    if len(ex) == 1:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + ex[0] + ' diyebilirsiniz ya da kartınızın son dört hanesini söyleyebilirsiniz.'
    return 'Hangi kartınızın borcunu öğrenmek istersiniz? Kartınızın son dört hanesini söyleyebilirsiniz.'
def all_names(cs):
    ex = []
    for c in cs:
        if c['main'] and cname(c) not in ex:
            ex.append(cname(c))
    return ', '.join(ex)

try:
    vars['sw_flag'] = ''
except Exception as _e:
    vars['runtime_error'] = str(_e)[:300]

