try:
    a_name = r"""{{card_name}}~"""[:-1]
    a_dig = r"""{{digits}}~"""[:-1]
    if '{' in a_name:
        a_name = ''
    if '{' in a_dig:
        a_dig = ''
    cs = cards()
    q = sel_question(cs)
    dig = re.sub(r'\D', '', a_dig)
    nm = norm(a_name)
    for w in ('kartım', 'kartımın', 'kartı', 'kart', 'olan', 'isimli'):
        nm = ' '.join([t for t in nm.split() if t != w])
    tries = int(num(sv('sel_tries')))
    pend = sv('sel_pending')
    cand = []
    say = ''
    def by_name(n):
        ex = [c for c in cs if norm(c['name']) == n and c['name']]
        if ex:
            return ex
        toks = n.split()
        r = [c for c in cs if c['name'] and all(t in norm(c['name']).split() for t in toks)]
        if r:
            return r
        toks2 = [t for t in toks if t != 'yıldız']
        if toks2:
            return [c for c in cs if c['name'] and all(t in norm(c['name']) for t in toks2)]
        return []
    if len(dig) >= 4:
        pool = cs
        if pend:
            pp = [c for c in cs if norm(c['name']) == pend]
            if pp:
                pool = pp
        cand = [c for c in pool if c['l4'] == dig[-4:]]
        if not cand and pool is not cs:
            cand = [c for c in cs if c['l4'] == dig[-4:]]
        if len(cand) > 1 and len(dig) >= 6:
            full = [c for c in cand if '*' not in c['n']]
            if full and len(full) == len(cand):
                f2 = [c for c in cand if c['n'].endswith(dig) or c['n'] == dig]
                if f2:
                    cand = f2
            elif len(dig) >= 16:
                f2 = [c for c in cand if c['n'][:6] == dig[:6]]
                if f2:
                    cand = f2
        if len(cand) > 1:
            if len(dig) < 6:
                say = 'Son dört hanesi ' + spaced(dig[-4:]) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
            else:
                say = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
            cand = []
        elif not cand:
            tries += 1
            say = 'Bu bilgilerle eşleşen bir kartınızı bulamadım. ' + q
    elif nm:
        cand = by_name(nm)
        names = []
        for c in cand:
            if c['name'] not in names:
                names.append(c['name'])
        if len(cand) > 1 and len(names) == 1:
            vars['sel_pending'] = norm(names[0])
            say = names[0] + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?'
            cand = []
        elif len(cand) > 1:
            say = 'Hangisini kastettiğinizi anlayamadım. Kartlarınız: ' + ', '.join(names) + '. Hangi kartınızın borcunu öğrenmek istersiniz?'
            cand = []
        elif not cand:
            tries += 1
            say = 'Bu isimde bir kartınız bulunmuyor. Kartlarınız: ' + all_names(cs) + '. Hangi kartınızın borcunu öğrenmek istersiniz?'
    else:
        tries += 1
        say = 'Kart borçlarını tek tek okuyabiliyorum. ' + q
    if len(cand) == 1 and not cand[0]['main']:
        tries += 1
        say = 'Bu kart ek kart olduğu için ekstre borcu sorgulamaya uygun değil. Lütfen başka bir kartınızı seçin. ' + q
        cand = []
    vars['sel_tries'] = str(tries)
    if len(cand) == 1:
        vars['sel_card'] = cand[0]['n']
        vars['sel_l4'] = cand[0]['l4']
        vars['sel_name'] = cand[0]['name']
        vars['sel_pending'] = ''
        vars['sel_tries'] = '0'
        vars['sel_flag'] = 'ok'
    elif tries >= 3:
        vars['sel_flag'] = 'fail'
    else:
        vars['select_prompt'] = say
        vars['sel_flag'] = 'say'
except Exception as _e:
    vars['runtime_error'] = str(_e)[:300]

